import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as o,c as n,o as i,ag as t,G as r}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const w=JSON.parse('{"title":"T3 Code getting started: install it, run your first thread, continue from your phone","description":"T3 Code is an open-source local app that ships no model of its own. It drives the coding agents already installed and signed in on your computer, lets them share one interface, one approval flow and one change view, and lets you continue from your phone after you leave the computer. This page walks you through installing it, running your first thread, learning the permission modes and remote access, and stating three security boundaries.","frontmatter":{"title":"T3 Code getting started: install it, run your first thread, continue from your phone","description":"T3 Code is an open-source local app that ships no model of its own. It drives the coding agents already installed and signed in on your computer, lets them share one interface, one approval flow and one change view, and lets you continue from your phone after you leave the computer. This page walks you through installing it, running your first thread, learning the permission modes and remote access, and stating three security boundaries.","domain":"product","tags":["coding-agent","agent-workspace","remote-access"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"products/t3code/t3code.md","filePath":"products/t3code/t3code.md","lastUpdated":1795792629000}'),h={name:"products/t3code/t3code.md"};function d(l,e,c,p,g,u){const s=o("DocDiagram");return i(),n("div",null,[e[0]||(e[0]=t("",48)),r(s,{src:"/diagrams/t3code-thread-lifecycle.en.svg",alt:"This sequence diagram answers two questions in numbered order: after you send a message in the interface, which stages does it pass through before it becomes one agent turn, and when the agent asks for permission, how does that request reach you and how does your decision get back to it? The diagram has six columns. The first is you: the desktop, web, or mobile client. The next three belong to the T3 Code server: the Orchestrator only decides events and effects and does no input or output; the EventSink writes to the database; the EffectWorker runs effects after commit. The fifth column is the Provider adapter, which translates T3 Code's operations and events into each agent's protocol. The sixth is the external agent process, for example the Claude Code or Codex command-line process. Solid lines are commands or calls; dashed lines are events, notices, and returns. Step 1: you send a command over authenticated RPC. Step 2: the Orchestrator decides the events plus one effect, which starts a provider turn. Step 3: the EventSink writes the events, projections, command receipt, and pending effect in one database transaction. Only after commit are subscribers told, which is when your message appears in the client. Step 4: the EffectWorker picks up the effect after commit and calls the Provider adapter. Step 5: the adapter calls startTurn on the external agent process with the policy for the permission mode, and the agent starts. Step 6: the agent process emits events; the adapter translates them into unified events, which go back to the Orchestrator as commands, are stored, and are pushed to the client as text deltas and tool calls. Step 7: when the agent process requests permission, the adapter first checks the permission mode: allow or deny is answered at once; only ask creates a pending request, called a runtime_request, which appears in the thread. Step 8: you approve or reject, and the client sends a response command; the Orchestrator marks the request resolved and stores it; the EffectWorker calls the adapter's respondToRuntimeRequest, the decision goes back to the agent process, and the agent continues. Three relationships to remember: the interface never talks to the agent directly, and every client reaches the server over authenticated RPC; each provider's differences stay behind the adapter, and the Orchestrator and the interface read only the capabilities the adapter declares; approvals and messages share one channel, both are stored before they are delivered, so approving on the phone and approving on the computer is the same flow. This diagram leaves out the concrete interface and buttons, the internal steps of model inference, and the T3 Connect relay, which is not on the path of business data. T3 Code does not run a model itself.",width:1020,lang:"en"}),e[1]||(e[1]=t("",115))])}const b=a(h,[["render",d]]);export{w as __pageData,b as default};
